python -c "
import wandb; api = wandb.Api()
runs = api.runs('wandb-applied-ai-team/kagent-v1', filters={'tags': 'score', 'state': 'finished'}, order='+summary_metrics.test/overall/mae_surf_p', per_page=50)
# Group by agent, show best per agent
best = {}
for r in runs[:50]:
    tp = r.summary.get('test/overall/mae_surf_p', None)
    if tp is None: continue
    agent = r.name.split('/')[1] if '/' in r.name else r.name
    if agent not in best or tp < best[agent][0]:
        best[agent] = (tp, r.name)
for agent, (score, name) in sorted(best.items(), key=lambda x: x[1][0]):
    print(f'  {agent:15s} {score:8.2f}  ({name})')
" 2>/dev/null

